slots.stateAt:
// 由 analysis 运动表生成；不要手改
const state = {};
let tt0 = t;
if (tt0 < 0) tt0 = 0;
if (tt0 > 1.3863) tt0 = 1.3863;
let x0, y0;
if (tt0 <= 0.6931) { x0 = 0 + 2.0000*(tt0 - 0) - 2.0000*(1.0000 - Math.exp(-1.0000*(tt0 - 0))); y0 = 0.01; }
else if (tt0 <= 1.3863) { x0 = 0.3863 + 1*(tt0 - 0.6931); y0 = 0.01; }
else { x0 = 0.3863 + 1*(tt0 - 0.6931); y0 = 0.01; }
state.conductor_rod = { x: x0, y: y0, type: "conductor_rod" };
return state;

slots.drawFrame:
const xL = -1.2;          // 左侧支路（电容 + 开关）
const xR = 2.2;           // 导轨右端
const yTop = 0.41;        // 上导轨
const yBot = -0.39;       // 下导轨
const rx = state.conductor_rod.x;
const ry = state.conductor_rod.y;

// ── 竖直匀强磁场（垂直纸面向里）──
Draw.fieldDots({ x: -1.15, y: -0.36, w: 3.3, h: 0.74 }, { symbol: 'cross', nx: 12, ny: 5 });

// ── 平行导轨（静态基准）──
Draw.line([xL, yTop], [-0.78, yTop], { width: 3 });
Draw.line([-0.42, yTop], [xR, yTop], { width: 3 });
Draw.line([xL, yBot], [xR, yBot], { width: 3 });

// 上导轨上的定值电阻 R
Draw.box([-0.6, yTop], 0.36, 0.16);

// 导轨端点接线柱
Draw.circle([xL, yTop], 0.025);
Draw.circle([xL, yBot], 0.025);

// ── 左侧支路：电容 C ──
Draw.line([xL, yTop], [xL, 0.23], { width: 2 });
Draw.line([xL - 0.18, 0.23], [xL + 0.18, 0.23], { width: 3 });
Draw.line([xL - 0.18, 0.14], [xL + 0.18, 0.14], { width: 3 });
Draw.line([xL, 0.14], [xL, 0.0], { width: 2 });

// ── 左侧支路：开关 S ──
Draw.circle([xL, -0.2], 0.028);
if (t < 0.6931) {
  Draw.line([xL, -0.2], [xL, 0.0], { width: 2 });          // 闭合
} else {
  Draw.line([xL, -0.2], [xL + 0.14, -0.05], { width: 2 });  // 断开
}
Draw.line([xL, -0.2], [xL, yBot], { width: 2 });

// ── 导体棒（始终垂直、两端落在导轨上）──
Draw.line([rx, ry - 0.4], [rx, ry + 0.4], { width: 5 });
Draw.circle([rx, ry], 0.03);

// ── 水平外力（闭合阶段向右恒力）──
if (t < 0.6931) {
  Draw.arrow([rx, ry], [1, 0], { category: 'force', mag: 2 });
}

slots.readouts:
// 由 analysis 运动表生成；曲线图直接读这里
const out = [];
const h = 1e-4;
const tA = Math.max(0, t - h);
const tB = Math.min(1.3863, t + h);
const a = stateAt(tA);
const b = stateAt(tB);
const dt = (tB - tA) || 1;
out.push({ key: "conductor_rod.x", label: "conductor_rod 水平位置", value: state.conductor_rod.x, unit: 'm' });
out.push({ key: "conductor_rod.y", label: "conductor_rod 竖直位置", value: state.conductor_rod.y, unit: 'm' });
out.push({ key: "conductor_rod.vx", label: "conductor_rod 水平速度", value: (b.conductor_rod.x - a.conductor_rod.x) / dt, unit: 'm/s' });
out.push({ key: "conductor_rod.vy", label: "conductor_rod 竖直速度", value: (b.conductor_rod.y - a.conductor_rod.y) / dt, unit: 'm/s' });
return out;
